    landing_workflow_title: "AATRAL எப்படி வேலை செய்கிறது - எளிமையாக & வெளிப்படையாக",
    landing_workflow_desc: "வீடுகள் மற்றும் பெரிய பொது நிறுவனங்களை சரிபார்க்கப்பட்ட கூட்டுறவு கைவினைஞர்களுடன் இணைக்கும் டிஜிட்டல் பாலம்:",
