    landing_flow1_subtitle: "வீட்டு உரிமையாளர்கள், வாடகைதாரர்கள் மற்றும் சிறிய அலுவலகங்களுக்கு",
    landing_flow1_btn: "வாடிக்கையாளர் முன்பதிவை முயற்சிக்கவும்",
    landing_flow1_step1_title: "சேவை தேவை",
    landing_flow1_step1_desc: "மின்சாரம், பிளம்பிங், தச்சு, சுத்தம் செய்தல் போன்றவற்றைத் தேர்ந்தெடுக்கவும்.",
    landing_flow1_step2_title: "சரிபார்க்கப்பட்ட பணியாளரைக் கண்டறியவும்",
    landing_flow1_step2_desc: "அருகிலுள்ள NCVT சான்றளிக்கப்பட்ட தொழிலாளர் கூட்டுறவு சங்க கைவினைஞர்களுடன் இணைக்கப்பட்டது.",
    landing_flow1_step3_title: "முன்பதிவு / அட்டவணை",
    landing_flow1_step3_desc: "30-நிமிட அவசர அழைப்பு அல்லது விருப்பமான தேதி, நேரம் மற்றும் முகவரியைத் தேர்வு செய்யவும்.",
    landing_flow1_step4_title: "பணியாளர் சேவையைச் செய்கிறார்",
    landing_flow1_step4_desc: "நேரடி ஜிபிஎஸ் கண்காணிப்பு, பாதுகாப்பான தொடக்க OTP மற்றும் வெளிப்படையான கட்டணம்.",
    landing_flow1_step5_title: "பணம் மற்றும் கருத்து",
    landing_flow1_step5_desc: "நேரடி UPI/கார்டு செலுத்துதல், இதில் 88% பணியாளரைச் சென்றடைகிறது.",
    landing_flow2_title: "நிறுவன மற்றும் அரசு கொள்முதல் ஓட்டம்",
    landing_flow2_subtitle: "மெட்ரோ ரயில், CPWD, மருத்துவமனைகள் மற்றும் நிறுவனங்களுக்கு",
    landing_flow2_btn: "எண்டர்பிரைஸ் போர்ட்டலை ஆராயுங்கள்",
    landing_flow2_step1_title: "பெரிய பணி தேவை",
    landing_flow2_step1_desc: "பல தொழிலாளர் வர்த்தகங்களுக்கான தேவையை நிறுவனம் பதிவு செய்கிறது.",
    landing_flow2_step2_title: "கூட்டுறவு ஆர்டரைப் பெறுகிறது",
    landing_flow2_step2_desc: "கூட்டமைப்பு விவரக்குறிப்புகள், பாதுகாப்பு மற்றும் சட்டரீதியான இணக்கத்தை மதிப்பாய்வு செய்கிறது.",
    landing_flow2_step3_title: "பணியாளர்களை திட்டமிட AI உதவுகிறது",
    landing_flow2_step3_desc: "அல்காரிதம்கள் கைவினைஞர்களின் இருப்பு மற்றும் குறைந்தபட்ச பயண தூரத்தை மேம்படுத்துகின்றன.",
    landing_flow2_step4_title: "பல பணியாளர்கள் ஒதுக்கப்பட்டுள்ளனர்",
    landing_flow2_step4_desc: "மேற்பார்வையாளர்கள் மற்றும் பாதுகாப்பு கியர்களுடன் சரிபார்க்கப்பட்ட குழுக்களை கூட்டுறவு சங்கங்கள் திரட்டுகின்றன.",
    landing_flow2_step5_title: "திட்டம் முடிந்தது",
    landing_flow2_step5_desc: "டிஜிட்டல் வருகை பதிவு மற்றும் தினசரி செக்-இன் தணிக்கைகள்.",
    landing_flow2_step6_title: "தீர்வு மற்றும் வருமானம்",
    landing_flow2_step6_desc: "எஸ்க்ரோ நிதிகள் நேரடியாக பணியாளர் பாஸ்புக்குகளில் வெளியிடப்படுகின்றன.",
    landing_coop_badge: "கூட்டுறவு அதிகாரமளித்தல் கட்டமைப்பு",
    landing_coop_title: "“ஒரு சந்தையை விட அதிகம்.”",
    landing_coop_desc: "AATRAL என்பது முறைசாரா தொழிலாளர்களை அங்கீகரிக்கப்பட்ட, கண்ணியமான கூட்டுறவு நிறுவனங்களாக உயர்த்த வடிவமைக்கப்பட்ட ஒரு விரிவான டிஜிட்டல் அமைப்பாகும்.",
    landing_val1_title: "கூட்டுறவு சங்கங்கள் தங்கள் உறுப்பினர்களை நிர்வகிக்கின்றன",
    landing_val1_desc: "பட்டியல்கள், வாக்களிப்பு மற்றும் சமூக நல நிதிகளைக் கண்காணிக்க ஆரம்ப தொழிலாளர் சங்கங்களுக்கான டிஜிட்டல் பதிவேடுகள்.",
    landing_val2_title: "பணியாளர் அடையாளம், உறுப்பினர் மற்றும் திறன்களை சரிபார்க்கவும்",
    landing_val2_desc: "டிஜிலாக்கர் e-KYC, NCVT சான்றிதழ்கள் மற்றும் உறுப்பினர் புத்தகங்களை இணைக்கும் 3-அடுக்கு சரிபார்ப்பு.",
    landing_val3_title: "கிடைக்கக்கூடிய உறுப்பினர்களுக்கான வேலையைக் கண்டறியவும்",
    landing_val3_desc: "சில்லறை வீட்டு சேவைகள் மற்றும் பொதுத்துறை ஒப்பந்தங்கள் இரண்டையும் சரிபார்க்கப்பட்ட கைவினைஞர்களுக்கு அனுப்புவதன் மூலம் வருமானத்தை விரிவுபடுத்துகிறது.",
    landing_val4_title: "பணியாளர் குறைவான பயன்பாட்டைக் குறைக்கவும்",
    landing_val4_desc: "நேரடி திறன் மற்றும் பயன்பாட்டு ரேடார், செயலற்ற நேரங்களை கொடியிடுகிறது.",
    landing_val5_title: "திறன், இடம் மற்றும் இருப்பு மூலம் பணியாளர்களை ஒதுக்குங்கள்",
    landing_val5_desc: "சிறந்த கைவினைஞரை ஒதுக்க துல்லியமான தூரம், தரம் மற்றும் கிடைக்கும் தன்மையை மல்டி-ஃபாக்டர் மேட்சிங் எஞ்சின் ஒருங்கிணைக்கிறது.",
    landing_val6_title: "வருவாய் மற்றும் விரிவான நலனைக் கண்காணிக்கவும்",
    landing_val6_desc: "உத்தரவாதமான 88% நேரடி ஊதியம், ₹5,00,000 விபத்து காப்பீடு மற்றும் கருவி சேத பழுதுபார்ப்பு மானியங்கள்.",
