    landing_ai_desc: "எங்கள் நரம்பியல் வலையமைப்பு பருவங்கள் மற்றும் வானிலை நிகழ்வுகள் முழுவதும் வர்த்தக கூர்முனைகளை கணிக்கிறது.",
